import json
from collections import Counter
path="observed_run/experiment_logs/rollout_records.jsonl"
type_counts=Counter()
seglen=Counter()
examples={}
nleaf_with_mismatch=0
for line in open(path,encoding="utf-8"):
    r=json.loads(line)
    for leaf_mismatches in r.get("tito_session_mismatch") or []:
        if leaf_mismatches:
            nleaf_with_mismatch+=1
        for m in leaf_mismatches:
            type_counts[m.get("type")]+=1
            t=m.get("type")
            if t not in examples:
                ex=dict(m)
                for k in ("expected_text","actual_text"):
                    v=ex.get(k)
                    if isinstance(v,str):
                        ex[k]=f"[len={len(v)}] head={v[:80]!r} tail={v[-80:]!r}"
                examples[t]=ex
print("type counts:",dict(type_counts))
print("leaves carrying mismatch lists:",nleaf_with_mismatch)
for t,ex in examples.items():
    print("== example type",t)
    print(json.dumps(ex,ensure_ascii=False,indent=1)[:1400])
